          "correctAnswer": 3,
          "explanation": "<b>Đáp án đúng: 3 (まいった)</b><br><b>Từ vựng & Mẫu câu:</b> まいった (Khổ sở, điêu đứng, chịu thua - dạng khẩu ngữ của 参る), thường dùng kèm thể bị động phiền toái (子どもに泣かれて).<br><b>Dịch câu:</b> Tối qua con khóc suốt cả đêm làm tôi khổ sở vô cùng.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. しまった:</b> V-て + しまった (Lỡ làm gì / hoàn tất), không đứng độc lập sau dấu phẩy như một vị ngữ diễn tả tâm trạng.<br>• <b>2. おそれいった:</b> 恐れ入る (Kinh ngạc, nể phục hoặc áy náy quá mức), sai ngữ cảnh than phiền.<br>• <b>3. まいった:</b> Đúng. Diễn tả cảm giác mệt mỏi, bó tay, khổ sở vì bị con quấy khóc suốt đêm.<br>• <b>4. まよった:</b> 迷った (Bị lạc đường / phân vân, lưỡng lự), không hợp nghĩa."
