          "explanation": "<b>Đáp án đúng: 3 (言わずにはいられなかった)</b><br><b>Cấu trúc:</b> V-ない (bỏ ない) + ずにはいられない (Không thể nhịn được, không thể không làm gì một cách tự nhiên/bộc phát).<br><b>Dịch câu:</b> Nửa đêm tiếng cười của mấy người phòng bên cạnh quá to nên tôi không thể không lên tiếng phàn nàn.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. 言ってはいられなかった:</b> V-てはいられない (Không thể cứ mãi làm gì đó - vì gấp gáp/tình huống không cho phép), sai nghĩa.<br>• <b>2. 言わざるをえなかった:</b> V-ざるを得ない (Buộc lòng phải làm vì nghĩa vụ/hoàn cảnh khách quan), mang sắc thái trang trọng/cứng và thiên về lý trí hơn là cảm xúc bộc phát ở đây.<br>• <b>3. 言わずにはいられなかった:</b> Đúng. Diễn tả sự bức xúc không thể kìm nén được nên phải lên tiếng.<br>• <b>4. 言うほかしかたがなかった:</b> Sai cấu trúc (ghép thừa giữa V-るほかない và V-るしかしかたがない)."
