          "explanation": "<b>Đáp án đúng: 2 (一方だ)</b><br><b>Cấu trúc:</b> V-る + 一方だ (Ngày càng... / Cứ thế tiếp tục theo một chiều hướng, thường dùng cho xu hướng tăng hoặc giảm tiêu cực).<br><b>Dịch câu:</b> Vì nhiều thanh niên trong ngôi làng này chuyển lên thành phố sinh sống nên dân số ngày càng giảm sút.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. だけしかない:</b> Dùng thừa cả だけ và しか (chỉ có mỗi...), sai tự nhiên và sai nghĩa biến đổi liên tục.<br>• <b>2. 一方だ:</b> Đúng. Diễn tả dân số cứ giảm dần theo một chiều hướng không dừng.<br>• <b>3. ことになった:</b> 'Đã được quyết định là...', dân số giảm là hiện tượng tự nhiên chứ không phải quyết định.<br>• <b>4. つもりだ:</b> 'Dự định là...', chỉ ý định của người, không dùng cho dân số."
