          "explanation": "<b>Đáp án đúng: 2 (こと)</b><br><b>Cấu trúc:</b> V-る / V-ない + こと (Quy định, mệnh lệnh, nội quy được viết trong thông báo/bảng hướng dẫn: Phải...).<br><b>Dịch câu:</b> Luận văn phải nộp muộn nhất là trước ngày 10 tháng 12.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. もの:</b> Không có mẫu V-る + もの đứng cuối câu để ra quy định thông báo.<br>• <b>2. こと:</b> Đúng. Câu thông báo quy định hạn nộp luận văn.<br>• <b>3. ものだ:</b> Diễn tả chân lý tự nhiên, đạo lý hiển nhiên hoặc cảm thán, không dùng để nêu hạn nộp cụ thể ngày 10/12.<br>• <b>4. ことだ:</b> V-る + ことだ dùng để đưa ra lời khuyên cá nhân ('nên làm gì'), không phải quy định hành chính."
