          "mondaiName": "問題７：文の文法１ (Ngữ pháp câu đơn - N3 Cốt Lõi)",
          "sentence": "A「すみません。英和辞典をお持ちでしたら、ちょっと貸していただけませんか。」<br>B「英和辞典（　　）そこにありますよ。はい、どうぞ。」",
