          "explanation": "<b>Đáp án đúng: 1 (おかげ)</b><br><b>Cấu trúc:</b> N の + おかげで: Nhờ có... / Nhờ ơn... (dùng cho kết quả tốt đẹp).<br><b>Dịch câu:</b> Nhờ có sự dìu dắt của thầy giáo mà em đã đỗ vào đại học một cách thuận lợi.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. おかげ:</b> Thể hiện lòng biết ơn vì kết quả tốt (đỗ đại học).<br>• <b>2. せい:</b> Tại vì... (dùng cho kết quả xấu, mang hàm ý đổ lỗi).<br>• <b>3. ため:</b> Vì / Để (sắc thái trung tính, nhưng với người giúp đỡ như 先生 thì phải dùng おかげ).<br>• <b>4. わけ:</b> Lý do/ý nghĩa, không có dạng 「先生のわけで」."
