          "explanation": "<b>Đáp án đúng: 1 (を対象に)</b><br><b>Cấu trúc:</b> N + を対象に（して）: Lấy ai/cái gì làm đối tượng (để khảo sát, nghiên cứu, phục vụ...).<br><b>Dịch câu:</b> Công ty A trước khi tung ra sản phẩm mới đã tiến hành khảo sát lấy đối tượng là 100 bà nội trợ.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. を対象に:</b> Chủ thể đối tượng của cuộc khảo sát (100 bà nội trợ).<br>• <b>2. を中心に:</b> Lấy... làm trung tâm (ví dụ trung tâm khu vực hoặc nhân vật chính, không hợp bằng を対象に cho số lượng đối tượng khảo sát cụ thể).<br>• <b>3. をはじめ:</b> Tiêu biểu là / Trước hết phải kể đến (liệt kê ví dụ tiêu biểu).<br>• <b>4. をもとに:</b> Dựa trên nền tảng/tài liệu (như dữ liệu, câu chuyện), không dùng cho người được khảo sát."
