          "correctAnswer": 1,
          "explanation": "<b>Đáp án đúng: 1 (なさそう)</b><br><b>Cấu trúc phán đoán:</b> Tính từ ない (không có) khi kết hợp với そうだ (có vẻ như) biến đổi đặc biệt thành なさそうだ.<br><b>Dịch câu:</b> Tôi đã rủ 'Đi cùng không?' nhưng trông cô ấy có vẻ chẳng hứng thú chút nào.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. なさそう:</b> Biến đổi đúng quy tắc của ない + そう → なさそう (trông có vẻ không có hứng thú).<br>• <b>2. なさげ:</b> Dạng văn học ít dùng phổ biến trong mẫu chuẩn N3 này và thường dùng với tính từ cảm xúc (さみしげ, 楽しげ).<br>• <b>3. ないそう:</b> Nghĩa là 'nghe nói là không có' (truyền văn), không khớp với だった và ngữ cảnh nhìn biểu cảm trực tiếp.<br>• <b>4. ないらしい:</b> Có vẻ như không (không đi với だった theo kiểu tính từ đuôi な như なさそうだった)."
