          "correctAnswer": 1,
          "explanation": "<b>Đáp án đúng: 1 (教えていただいた)</b><br><b>Kính ngữ mang ơn:</b> [Người dạy] に + V-ていただく: Được ai đó (bề trên) làm cho việc gì.<br><b>Dịch câu:</b> Nhờ được thầy giáo tiếng Nhật tận tình chỉ bảo mà khả năng giao tiếp của tôi đã tiến bộ rõ rệt.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. 教えていただいた:</b> Trợ từ là 「先生に」 nên động từ phải là いただく (khiêm nhường ngữ của もらう).<br>• <b>2. 教えてあげた:</b> Dạy cho thầy (ngược chủ thể hoàn toàn).<br>• <b>3. 教えてくださった:</b> くださる phải đi với chủ ngữ là 「先生が」(thầy đã dạy cho tôi), không dùng khi trợ từ là 「先生に」.<br>• <b>4. 教えてもらった:</b> Dùng đúng trợ từ に nhưng sắc thái thông thường, thiếu kính trọng khi nói về thầy giáo (先生)."
