          "correctAnswer": 1,
          "explanation": "<b>Đáp án đúng: 1 (だって)</b><br><b>Cấu trúc khẩu ngữ:</b> N + だって: Ngay cả... cũng... (nhấn mạnh mức độ tối thiểu trong văn nói).<br><b>Dịch câu:</b> Chuyện cỏn con như thế thì ngay cả một đứa học sinh tiểu học cũng biết rõ như lòng bàn tay.<br><b>Phân tích các lựa chọn:</b><br>• <b>1. だって:</b> Mang sắc thái khẩu ngữ tự nhiên, rất hợp với đuôi câu 「～ですよ」 để nhấn mạnh 'đến học sinh tiểu học còn biết nữa là'.<br>• <b>2. でも:</b> Cũng có nghĩa 'ngay cả', dùng phổ biến, nhưng trong đề thi N3 câu văn nói nhấn mạnh mạnh mẽ như thế này chọn だって làm điểm ngữ pháp trọng tâm.<br>• <b>3. さえ:</b> Ngay cả (thường mang sắc thái trang trọng hơn hoặc đi với thể điều kiện, ít dùng đơn thuần trong câu nói 「～ですよ」 bằng だって).<br>• <b>4. すら:</b> Ngay cả (thường dùng trong văn viết trang trọng hoặc câu mang nghĩa tiêu cực/ngạc nhiên)."
